use std::path::PathBuf;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use proxy_client::client::{
    ClientConfig, ClientRuntimeConfig, run_client_with_listener_runtime_config,
};
use proxy_core::config::{DEFAULT_SECRET_KEY, runtime};
use proxy_core::control::{ControlClient, ControlOp, ControlRequest, ControlResult};
use proxy_core::datagram::{DatagramAddress, encode_socks5_udp_packet, parse_socks5_udp_packet};
use proxy_core::metrics::MetricsStore;
use proxy_core::nodes::NodeStore;
use proxy_core::relay::ExternalProxyTarget;
use proxy_core::secure_transport::{WireProtocol, set_wire_protocol};
use proxy_server::{RelayManager, ServerConfig, run_server_with_listener};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpStream, UdpSocket};
use tokio::time::{Duration, timeout};
use tokio_util::sync::CancellationToken;

#[tokio::test]
async fn local_proxy_supports_plain_encrypted_http_and_udp_with_chained_relays() {
    for protocol in [WireProtocol::Legacy, WireProtocol::V3] {
        timeout(Duration::from_secs(30), protocol_round_trips(protocol))
            .await
            .unwrap();
    }
}

async fn protocol_round_trips(protocol: WireProtocol) {
    set_wire_protocol(protocol);
    let echo_socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
    let echo_addr = echo_socket.local_addr().unwrap();
    let echo_task = tokio::spawn(async move {
        let mut buffer = [0u8; 2048];
        while let Ok((size, peer)) = echo_socket.recv_from(&mut buffer).await {
            if echo_socket.send_to(&buffer[..size], peer).await.is_err() {
                break;
            }
        }
    });

    let server_listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let server_addr = server_listener.local_addr().unwrap();
    runtime::init_config(
        server_addr.ip().to_string(),
        server_addr.port(),
        false,
        Some(DEFAULT_SECRET_KEY.to_string()),
    );

    let state_dir = unique_temp_dir("socks5-udp");
    std::fs::create_dir_all(&state_dir).unwrap();
    let nodes = Arc::new(NodeStore::new(state_dir.join("nodes.json")));
    let server_config = ServerConfig {
        metrics: Arc::new(MetricsStore::with_default_config()),
        relay: Arc::new(RelayManager::new(nodes.clone(), &state_dir)),
        nodes,
        admin_token: None,
        require_control_encryption: true,
        require_secure_transport: protocol == WireProtocol::V3,
        control_session_key: Some(DEFAULT_SECRET_KEY.to_string()),
        self_node_id: None,
    };
    let server_cancel = CancellationToken::new();
    let server_task = tokio::spawn(run_server_with_listener(
        server_listener,
        server_config,
        server_cancel.clone(),
        None,
    ));

    // A live-switch probe must negotiate on the socket whose bypass was already
    // prepared, without another hostname lookup or connection. Exercise that
    // entry point against both supported wire protocols and the real server.
    let prepared_socket = TcpStream::connect(server_addr).await.unwrap();
    let session = proxy_core::session::NativeSession::from_tcp_stream(
        "",
        0,
        proxy_core::ProxyTransport::UdpAssociate,
        prepared_socket,
    )
    .await
    .unwrap();
    let (mut probe, _) = session.into_parts();
    assert_eq!(
        probe.read_u8().await.unwrap(),
        proxy_core::datagram::UDP_ASSOCIATION_READY
    );
    drop(probe);

    let mut control = ControlClient::connect(
        "127.0.0.1",
        server_addr.port(),
        Some(DEFAULT_SECRET_KEY.to_string()),
    )
    .await
    .unwrap();
    let response = control
        .request(ControlRequest {
            token: None,
            op: ControlOp::Ping,
        })
        .await
        .unwrap();
    assert!(matches!(response.result, Some(ControlResult::Pong)));
    drop(control);
    if protocol == WireProtocol::V3 {
        let mut legacy = TcpStream::connect(server_addr).await.unwrap();
        legacy.write_all(b"old!\0\0\0\x01").await.unwrap();
        assert!(legacy.read_u8().await.is_err());
    }

    let client_listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let client_addr = client_listener.local_addr().unwrap();
    let client_cancel = CancellationToken::new();
    let client_task = tokio::spawn(run_client_with_listener_runtime_config(
        client_listener,
        client_cancel.clone(),
        None,
        Some(ClientRuntimeConfig {
            client: ClientConfig {
                enable_auto_proxy: false,
                enable_udp: true,
                cache_dir: None,
            },
            upstream_proxy: None,
            tun: None,
            force_proxy: None,
            process_bypass: None,
        }),
    ));

    assert_udp_round_trip(
        client_addr,
        DatagramAddress::Ip(echo_addr),
        DatagramAddress::Ip(echo_addr),
        b"udp-through-encrypted-proxy",
        false,
    )
    .await;

    assert_udp_round_trip(
        client_addr,
        DatagramAddress::Ip(echo_addr),
        DatagramAddress::Ip(echo_addr),
        b"udp-after-malformed-unpinned-packet",
        true,
    )
    .await;
    assert_http_round_trip(client_addr).await;

    let chained_listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let chained_addr = chained_listener.local_addr().unwrap();
    let chained_cancel = CancellationToken::new();
    let chained_task = tokio::spawn(run_client_with_listener_runtime_config(
        chained_listener,
        chained_cancel.clone(),
        None,
        Some(ClientRuntimeConfig {
            client: ClientConfig {
                enable_auto_proxy: false,
                enable_udp: true,
                cache_dir: None,
            },
            upstream_proxy: Some(
                ExternalProxyTarget::parse(&format!("socks5h://{client_addr}")).unwrap(),
            ),
            tun: None,
            force_proxy: None,
            process_bypass: None,
        }),
    ));
    assert_udp_round_trip(
        chained_addr,
        // Keep ATYP=DOMAIN coverage while avoiding OS-dependent localhost
        // ordering (`::1` may precede `127.0.0.1` on Windows).
        DatagramAddress::Domain("127.0.0.1".to_string(), echo_addr.port()),
        DatagramAddress::Ip(echo_addr),
        b"udp-through-socks5-chain",
        false,
    )
    .await;

    if protocol == WireProtocol::V3 {
        let relay_listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let relay_addr = relay_listener.local_addr().unwrap();
        let relay_dir = unique_temp_dir("v3-opaque-relay");
        std::fs::create_dir_all(&relay_dir).unwrap();
        let relay_nodes = Arc::new(NodeStore::new(relay_dir.join("nodes.json")));
        let relay = Arc::new(RelayManager::new(relay_nodes.clone(), &relay_dir));
        relay.add_target(proxy_core::relay::UpstreamTarget::node(
            server_addr.to_string(),
        ));
        relay.set_enabled(true);
        let relay_config = ServerConfig {
            relay,
            nodes: relay_nodes,
            require_secure_transport: true,
            ..ServerConfig::default()
        };
        let relay_cancel = CancellationToken::new();
        let relay_task = tokio::spawn(run_server_with_listener(
            relay_listener,
            relay_config,
            relay_cancel.clone(),
            None,
        ));
        runtime::set_server_endpoint("127.0.0.1".to_string(), relay_addr.port());
        assert_udp_round_trip(
            client_addr,
            DatagramAddress::Ip(echo_addr),
            DatagramAddress::Ip(echo_addr),
            b"udp-after-malformed-unpinned-packet",
            true,
        )
        .await;
        assert_http_round_trip(client_addr).await;
        assert_udp_round_trip(
            client_addr,
            DatagramAddress::Ip(echo_addr),
            DatagramAddress::Ip(echo_addr),
            b"v3 opaque relay",
            false,
        )
        .await;
        // Control stays on the intermediate relay, identified by its different authorization
        // policy.
        let mut control = ControlClient::connect("127.0.0.1", relay_addr.port(), None)
            .await
            .unwrap();
        assert!(
            control
                .request(ControlRequest {
                    token: None,
                    op: ControlOp::Ping
                })
                .await
                .unwrap()
                .ok
        );
        drop(control);
        relay_cancel.cancel();
        relay_task.await.unwrap();
        let _ = std::fs::remove_dir_all(relay_dir);
    }

    chained_cancel.cancel();
    client_cancel.cancel();
    server_cancel.cancel();
    chained_task.await.unwrap();
    client_task.await.unwrap();
    server_task.await.unwrap();
    echo_task.abort();
    let _ = std::fs::remove_dir_all(state_dir);
}

#[tokio::test]
async fn socks5_udp_associate_returns_command_not_supported_when_disabled() {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let client_addr = listener.local_addr().unwrap();
    let cancel = CancellationToken::new();
    let task = tokio::spawn(run_client_with_listener_runtime_config(
        listener,
        cancel.clone(),
        None,
        Some(ClientRuntimeConfig {
            client: ClientConfig {
                enable_auto_proxy: false,
                enable_udp: false,
                cache_dir: None,
            },
            upstream_proxy: None,
            tun: None,
            force_proxy: None,
            process_bypass: None,
        }),
    ));

    let mut control = TcpStream::connect(client_addr).await.unwrap();
    control.write_all(&[0x05, 0x01, 0x00]).await.unwrap();
    let mut method = [0u8; 2];
    control.read_exact(&mut method).await.unwrap();
    assert_eq!(method, [0x05, 0x00]);

    control
        .write_all(&[0x05, 0x03, 0x00, 0x01, 127, 0, 0, 1, 0, 0])
        .await
        .unwrap();
    let mut response = [0u8; 10];
    control.read_exact(&mut response).await.unwrap();
    assert_eq!(response, [0x05, 0x07, 0x00, 0x01, 0, 0, 0, 0, 0, 0]);

    cancel.cancel();
    task.await.unwrap();
}

async fn assert_http_round_trip(client_addr: std::net::SocketAddr) {
    let destination = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let target = destination.local_addr().unwrap();
    let echo = tokio::spawn(async move {
        let (mut stream, _) = destination.accept().await.unwrap();
        let (mut reader, mut writer) = stream.split();
        tokio::io::copy(&mut reader, &mut writer).await.unwrap();
    });
    let mut stream = TcpStream::connect(client_addr).await.unwrap();
    let request = format!(
        "POST http://{target}/ HTTP/1.1\r\nHost: {target}\r\nContent-Length: 8\r\n\r\nbodydata"
    );
    stream.write_all(request.as_bytes()).await.unwrap();
    let mut response = vec![0; request.len()];
    timeout(Duration::from_secs(3), stream.read_exact(&mut response))
        .await
        .unwrap()
        .unwrap();
    assert_eq!(response, request.as_bytes());
    // A later write must continue the existing encryption nonce sequence.
    stream.write_all(b"later body").await.unwrap();
    let mut later = [0; 10];
    timeout(Duration::from_secs(3), stream.read_exact(&mut later))
        .await
        .unwrap()
        .unwrap();
    assert_eq!(&later, b"later body");
    drop(stream);
    timeout(Duration::from_secs(3), echo)
        .await
        .unwrap()
        .unwrap();
}

async fn assert_udp_round_trip(
    client_addr: std::net::SocketAddr,
    destination: DatagramAddress,
    expected_source: DatagramAddress,
    payload: &[u8],
    unspecified_port: bool,
) {
    let udp_client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
    let mut control = TcpStream::connect(client_addr).await.unwrap();
    control.write_all(&[0x05, 0x01, 0x00]).await.unwrap();
    let mut method = [0u8; 2];
    control.read_exact(&mut method).await.unwrap();
    assert_eq!(method, [0x05, 0x00]);

    let mut udp_client_addr = udp_client.local_addr().unwrap();
    if unspecified_port {
        udp_client_addr.set_port(0);
    }
    let mut request = vec![0x05, 0x03, 0x00];
    proxy_core::datagram::encode_socks5_address(
        &DatagramAddress::Ip(udp_client_addr),
        &mut request,
    )
    .unwrap();
    control.write_all(&request).await.unwrap();
    let relay_addr = read_socks5_reply(&mut control).await;

    // An explicit endpoint rejects other ports. A port-zero association must
    // ignore malformed first packets without pinning their source endpoint.
    let unexpected_client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
    let request = encode_socks5_udp_packet(&destination, payload).unwrap();
    let mut unexpected_request = request.clone();
    if unspecified_port {
        unexpected_request[2] = 1;
    }
    unexpected_client
        .send_to(&unexpected_request, relay_addr)
        .await
        .unwrap();
    let mut ignored_response = [0u8; 2048];
    assert!(
        timeout(
            Duration::from_millis(150),
            unexpected_client.recv_from(&mut ignored_response)
        )
        .await
        .is_err(),
        "UDP packet from an undeclared endpoint was unexpectedly relayed"
    );

    // RFC 1928 fragmentation is unsupported. The malformed datagram should
    // be dropped without tearing down the association, which is verified by
    // the valid round trip immediately afterwards.
    let mut fragmented_request = request.clone();
    fragmented_request[2] = 1;
    udp_client
        .send_to(&fragmented_request, relay_addr)
        .await
        .unwrap();
    assert!(
        timeout(
            Duration::from_millis(150),
            udp_client.recv_from(&mut ignored_response)
        )
        .await
        .is_err(),
        "fragmented SOCKS5 UDP packet was unexpectedly relayed"
    );

    udp_client.send_to(&request, relay_addr).await.unwrap();
    let mut response = [0u8; 2048];
    let (size, source) = timeout(Duration::from_secs(3), udp_client.recv_from(&mut response))
        .await
        .expect("SOCKS5 UDP response timed out")
        .unwrap();
    assert_eq!(source, relay_addr);
    let response = parse_socks5_udp_packet(&response[..size]).unwrap();
    assert_eq!(response.destination, expected_source);
    assert_eq!(response.payload, payload);
}

async fn read_socks5_reply(stream: &mut TcpStream) -> std::net::SocketAddr {
    let mut prefix = [0u8; 4];
    stream.read_exact(&mut prefix).await.unwrap();
    assert_eq!(&prefix[..3], &[0x05, 0x00, 0x00]);
    match prefix[3] {
        0x01 => {
            let mut body = [0u8; 6];
            stream.read_exact(&mut body).await.unwrap();
            let ip = std::net::Ipv4Addr::new(body[0], body[1], body[2], body[3]);
            let port = u16::from_be_bytes([body[4], body[5]]);
            std::net::SocketAddr::new(ip.into(), port)
        }
        0x04 => {
            let mut body = [0u8; 18];
            stream.read_exact(&mut body).await.unwrap();
            let mut octets = [0u8; 16];
            octets.copy_from_slice(&body[..16]);
            let port = u16::from_be_bytes([body[16], body[17]]);
            std::net::SocketAddr::new(std::net::Ipv6Addr::from(octets).into(), port)
        }
        atyp => panic!("unexpected SOCKS5 reply address type {atyp:#x}"),
    }
}

fn unique_temp_dir(name: &str) -> PathBuf {
    let suffix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    std::env::temp_dir().join(format!("proxy-everything-{name}-{suffix}"))
}

